from sympy import symbols, integrate, limit, sqrt, log, Rational

x = symbols("x", real=True)
u = symbols("u", positive=True)

def up_to(f, a, c):
    # from a up to the asymptote c: stop at c - u, then u -> 0+
    return limit(integrate(f, (x, a, c - u)), u, 0, "+")

def down_to(f, c, b):
    # from the asymptote c to b: start at c + u, then u -> 0+
    return limit(integrate(f, (x, c + u, b)), u, 0, "+")

def improper(label, f, a, b, c):
    print(label)
    pieces = []
    if c > a:
        pieces.append((a, c, up_to(f, a, c)))
    if c < b:
        pieces.append((c, b, down_to(f, c, b)))
    total = 0
    good = True
    for lo, hi, value in pieces:
        print(f"  {lo} to {hi}: {value}")
        if value.is_finite:
            total = total + value
        else:
            good = False
    if good:
        print(f"  converges to {total}")
    else:
        print("  diverges")

improper("Example 1 · blows up at 0: 1/sqrt(x) on [0, 1]", 1 / sqrt(x), 0, 1, 0)
improper("Example 2 · divergence: 1/x on [0, 1]", 1 / x, 0, 1, 0)
improper("Example 3 · the right end: 1/sqrt(3 - x) on [0, 3]", 1 / sqrt(3 - x), 0, 3, 3)
improper("Example 5 · a log: ln x on [0, 1]", log(x), 0, 1, 0)
improper("Example 6 · in the middle: 1/x^2 on [-1, 1]", 1 / x**2, -1, 1, 0)
improper("Example 7 · in the middle: 1/cbrt(x^2) on [-1, 8]", (x**2)**Rational(-1, 3), -1, 8, 0)

