from sympy import symbols, integrate, limit, sympify

x = symbols("x", real=True)
u = symbols("u", positive=True)

def up_to(f, a, c):
    return limit(integrate(f, (x, a, c - u)), u, 0, "+")

def down_to(f, c, b):
    return limit(integrate(f, (x, c + u, b)), u, 0, "+")

n = int(input())
for i in range(n):
    f = sympify(input(), locals={"x": x})
    a, b, c = [int(v) for v in input().split()]
    pieces = []
    if c > a:
        pieces.append((a, c, up_to(f, a, c)))
    if c < b:
        pieces.append((c, b, down_to(f, c, b)))
    total = 0
    good = True
    for lo, hi, value in pieces:
        print(f"{lo} to {hi}: {value}")
        if value.is_finite:
            total = total + value
        else:
            good = False
    if good:
        print(f"converges to {total}")
    else:
        print("diverges")

from fractions import Fraction

def far(c, p):
    if p > 1:
        return f"converges to {c / (p - 1)}"
    return "diverges"

def near_zero(c, p):
    if p < 1:
        return f"converges to {c / (1 - p)}"
    return "diverges"

n = int(input())
for i in range(n):
    words = input().split()
    c = Fraction(words[0])
    p = Fraction(words[1])
    where = words[2]
    if where == "far":
        print(far(c, p))
    elif where == "zero":
        print(near_zero(c, p))
    else:
        print("diverges")

from fractions import Fraction
from sympy import symbols, sympify

x = symbols("x")

n = int(input())
for i in range(n):
    f = sympify(input(), locals={"x": x})
    words = input().split()
    a = int(words[0])
    side = words[1]
    c = Fraction(words[2])
    p = Fraction(words[3])
    fails = 0
    for k in range(100):
        v = a + k
        d = float((f - c / x**p).subs(x, v))
        if (side == "below" and d > 0) or (side == "above" and d < 0):
            fails = fails + 1
    print(f"fails {fails} times")
    if p > 1:
        print("g converges")
    else:
        print("g diverges")
    if fails > 0:
        print("no conclusion")
    elif side == "below" and p > 1:
        print("converges")
    elif side == "above" and p <= 1:
        print("diverges")
    else:
        print("no conclusion")
